style.css:
@-moz-document url-prefix("https://www.google.com"), regexp("chrome://newtab") {
/* Arka Plan Görseli ve Ana Renkler */
    body, #ntp-contents, .ntp-background {
        background: linear-gradient(rgba(18, 30, 46, 0.45), rgba(18, 30, 46, 0.45)), 
                    url('https://4kwallpapers.com/images/wallpapers/castorice-butterfly-5120x2880-25920.jpg') no-repeat center center fixed !important;
        background-size: cover !important;
        background-color: #121e2e !important; /* Yedek renk */
    }

    /* Orta Alan - Cam Efekti */
    .RNNXgb, #ntp-search-box, .realbox {
        background: rgba(23, 32, 43, 0.5) !important;
        backdrop-filter: blur(20px) saturate(180%) !important;
        -webkit-backdrop-filter: blur(20px) saturate(180%) !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        border-radius: 24px !important;
        box-shadow: 0 10px 40px rgba(0, 0, 0, 0.4) !important;
    }

    /* Kısayol İkonlarını (Yeni Sekmedeki Yuvarlaklar) Düzenle */
    .most-visited, .ntp-content, .tile {
        background: rgba(255, 255, 255, 0.05) !important;
        backdrop-filter: blur(10px) !important;
        border-radius: 12px !important;
        border: 1px solid rgba(255, 255, 255, 0.1) !important;
        transition: 0.3s !important;
    }

    .most-visited:hover {
        background: rgba(255, 255, 255, 0.1) !important;
        transform: scale(1.05);
    }

    /* Metinleri Beyazlat */
    span, a, div {
        color: #f1f1f1 !important;
        text-shadow: 0 2px 4px rgba(0,0,0,0.3);
    }

    /* Logoyu Beyazlat (Yeni sekmede logo bazen farklı bir div içindedir) */
    #logo, .lnXpce, .k1zPbe {
        filter: invert(1) brightness(2) drop-shadow(0 0 10px rgba(255,255,255,0.2)) !important;
    }

    /* Alt Kısımdaki Çöp Öğeleri Gizle */
    #footer, #extabar, .p7Uzy, .K8vY6b {
        display: none !important;
    }
}
